// Varint encoding for 64-bit integers: continue encoding 7 bits at a time
// until there are no more bits left. The MSB of each byte indicates if
// there are more bytes to follow.
uint8_t* ptr = reinterpret_cast<uint8_t*>(std::string::value_type* dst->data() + dst->size());
uint64_t value = v;
do {
    uint8_t byte = value & 0x7F;
    value >>= 7;
    if (value != 0) {
        byte |= 0x80;
    }
    *ptr++ = byte;
} while (value != 0);
dst->resize(dst->size() + (ptr - reinterpret_cast<uint8_t*>(dst->data() + dst->size())));

